package java.util.concurrent;
import java.util.Random;
public class ThreadLocalRandom extends Random { private static final ThreadLocalRandom INSTANCE=new ThreadLocalRandom(); private ThreadLocalRandom(){} public static ThreadLocalRandom current(){return INSTANCE;} public int nextInt(int origin,int bound){if(origin>=bound)throw new IllegalArgumentException();return origin+nextInt(bound-origin);} public long nextLong(long bound){if(bound<=0)throw new IllegalArgumentException();return (nextLong()&Long.MAX_VALUE)%bound;} public long nextLong(long origin,long bound){if(origin>=bound)throw new IllegalArgumentException();return origin+nextLong(bound-origin);} public double nextDouble(double bound){if(bound<=0)throw new IllegalArgumentException();return nextDouble()*bound;} public double nextDouble(double origin,double bound){if(origin>=bound)throw new IllegalArgumentException();return origin+nextDouble()*(bound-origin);} }
